// Mirrors the state React's UsaBanner keeps: the same classes, attributes and `hidden` flags change.
const toggle = (button) => {
  const banner = button.closest(".ds-c-usa-banner")
  const expanded = button.getAttribute("aria-expanded") !== "true"

  button.setAttribute("aria-expanded", String(expanded))
  banner.querySelector(".ds-c-usa-banner__header").classList.toggle("ds-c-usa-banner__header--expanded", expanded)
  banner.querySelector(".ds-c-usa-banner__action").classList.toggle("ds-u-display--flex", !expanded)
  banner.querySelector(".ds-c-usa-banner__button-icon-container").hidden = !expanded
  banner.querySelector(".ds-c-usa-banner__guidance-container").hidden = !expanded

  const [from, to] = expanded ? ["down", "up"] : ["up", "down"]
  for (const icon of banner.querySelectorAll(".ds-c-usa-banner__action-icon")) {
    icon.classList.replace(`ds-c-icon--arrow-${from}`, `ds-c-icon--arrow-${to}`)
    icon.setAttribute("direction", to)
  }
}

document.addEventListener("click", (event) => {
  const button = event.target.closest(".ds-c-usa-banner__button")
  if (button) toggle(button)
})
